CREATE TABLE app_records (id TEXT PRIMARY KEY, collection TEXT NOT NULL, body TEXT NOT NULL CHECK(json_valid(body)));
CREATE INDEX app_records_collection ON app_records(collection);
CREATE TABLE app_revision (id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL);
INSERT INTO app_revision VALUES (1,0);
CREATE TABLE jobs (id TEXT PRIMARY KEY, path TEXT NOT NULL, args TEXT NOT NULL, due_at INTEGER NOT NULL, lease_until INTEGER, attempts INTEGER NOT NULL DEFAULT 0, error TEXT);
CREATE INDEX jobs_due ON jobs(due_at,lease_until);
CREATE TABLE documents (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL);
