CREATE UNIQUE INDEX users_auth_identity ON app_records(json_extract(body,'$.authUserId')) WHERE collection='users';
CREATE VIRTUAL TABLE app_search USING fts5(id UNINDEXED, collection UNINDEXED, name, tokenize='unicode61');
CREATE TRIGGER app_search_insert AFTER INSERT ON app_records WHEN new.collection='municipalities' BEGIN
  INSERT INTO app_search(id,collection,name) VALUES(new.id,new.collection,json_extract(new.body,'$.name'));
END;
CREATE TRIGGER app_search_update AFTER UPDATE ON app_records WHEN new.collection='municipalities' BEGIN
  DELETE FROM app_search WHERE id=old.id;
  INSERT INTO app_search(id,collection,name) VALUES(new.id,new.collection,json_extract(new.body,'$.name'));
END;
CREATE TRIGGER app_search_delete AFTER DELETE ON app_records WHEN old.collection='municipalities' BEGIN
  DELETE FROM app_search WHERE id=old.id;
END;
